[NG_FFCutsFits,FileResName] = recover_selected_cuts('NG_FFCutsFits','e:\SHARE\Fe\Data\analysis\07_fit_with_multicut_allJ\sel_cuts');
fn = fieldnames(NG_FFCutsFits);
save_result = false;
for i=1:numel(fn)
    fldVal  = NG_FFCutsFits.(fn{i});
    if iscell(fldVal) && isscalar(fldVal) && isa(fldVal{1},'sqw')
        save_result = true;
        NG_FFCutsFits.(fn{i}) = fldVal{1};
    end
end
if save_result
    save(FileResName,'NG_FFCutsFits','-v7.3');
end


