%init_fg_params = [coffect_ff,T,gamma,Seff, gap, J0, J1, J2, J3, J4];
free_sw_param  =  [0          0, 1   ,1   , 0,    1, 1,   0,  0,  0];
selCut = NG_FFCutsFits.Ei400_off200NGmaxFF;
mi = maps_instrument(401,600,'S');
sample=IX_sample(true,[1,0,0],[0,1,0],'cuboid',[0.04,0.03,0.02]);
selCut = selCut.set_instrument(mi);
selCut = selCut.set_sample(sample);

plot(selCut); lz 0 1;keep_figure; %[output:350f1cd8]
