cuts = cell(1,numel(e_sel));
for i=1:numel(e_sel) %[output:group:79933e25]
    cuts{i} = cut(selCut,[],[e_sel(i)-5,e_sel(i)+5]); %[output:1246f0d3]
    plot(cuts{i}); %[output:3029c8ba]
end %[output:group:79933e25]

