kk = tobyfit(cuts{:});
kk = kk.set_local_foreground;
kk = kk.set_fun(@sqw_iron);

hkl_proj = selCut.data.proj;
kk = kk.set_pin({init_fg_param,hkl_proj});
kk = kk.set_free(free_sw_param);

kk = kk.set_bind({{6,[6,1]},{7,[7,1]}});

kk = kk.set_bfun (@linear_bg1D); % set_bfun sets the background functions
%
%bg_param = init_bg_param(valid);
kk = kk.set_bpin ([0,0]);  % initial background constant and gradient
kk = kk.set_bfree ([1,0]);

kk = kk.set_options('list',2);

[fit_obj,fit_par] = kk.fit(); %[output:51aed2b9]
%%
for i=1:numel(cuts) %[output:group:515b0a69]
    plot(cuts{i}); %[output:1cf31b7d] %[output:443cb54b] %[output:11ff2bbd] %[output:00b2503b] %[output:00efd394]
    pl(fit_obj{i}); keep_figure
end %[output:group:515b0a69]

